{'code': "from qgis.core import QgsApplication
import json
alg = QgsApplication.processingRegistry().algorithmById('gdal:griddatametrics')
result = None
if alg:
    defs = {p.name(): p for p in alg.parameterDefinitions()}
    def opts(name):
        p = defs.get(name)
        try:
            return list(p.options()) if p is not None else None
        except Exception:
            return None
    result = json.dumps({
        'metric_options': opts('METRIC'),
        'data_type_options': opts('DATA_TYPE')
    }, ensure_ascii=False)"}
